const SizedBox(height: 18),
ValueListenableBuilder<bool>(
  valueListenable: widget.game.canGiveGiftListenable,
  builder: (context, canGift, child) {
    final choices = widget.game.availableDialogueChoices;
    final firstGiftIndex = choices.indexWhere(
      (choice) => choice.isGift,
    );
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        for (final (index, choice) in choices.indexed) ...[
          if (index > 0) const SizedBox(height: 10),
          FilledButton.icon(
            key: index == firstGiftIndex
                ? DialogueOverlay.giftButtonKey
                : DialogueOverlay.choiceButtonKey(choice.id),
            onPressed: () =>
                widget.game.selectDialogueChoice(choice.id),
            autofocus: index == 0,
            focusNode: index == 0 ? _firstActionFocusNode : null,
            icon: Icon(
              choice.isGift
                  ? Icons.card_giftcard
                  : Icons.chat_bubble_outline,
            ),
            label: Padding(
              padding: const EdgeInsets.symmetric(vertical: 10),
              child: Text(choice.text, textAlign: TextAlign.center),
            ),
          ),
        ],
        if (node.continueTargetId != null) ...[
          if (choices.isNotEmpty) const SizedBox(height: 10),
          FilledButton.icon(
            key: DialogueOverlay.continueButtonKey,
            onPressed: widget.game.continueDialogue,
            autofocus: choices.isEmpty,
            focusNode: choices.isEmpty ? _firstActionFocusNode : null,
            icon: const Icon(Icons.arrow_forward),
            label: const Text('Continue'),
          ),
        ],
        if (choices.isEmpty && node.continueTargetId == null)
          OutlinedButton(
            onPressed: widget.game.closeDialogue,
            autofocus: true,
            focusNode: _firstActionFocusNode,
            child: const Text('End conversation'),
          ),
      ],
    );
